<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { supabase } from '../lib/supabase'
import { useApp } from '../stores/app'
const props=defineProps<{linkId:string}>(),app=useApp(),opened=ref(false),busy=ref(false),error=ref(''),rows=ref<{id:string;url:string;attribution:string;is_ai_generated:boolean}[]>([]),file=ref<File>(),attribution=ref(''),ai=ref(false)
async function load(){if(app.demo||!supabase)return;busy.value=true;error.value='';try{const r=await supabase.from('link_attachments').select('id,storage_path,attribution,is_ai_generated').eq('link_id',props.linkId);if(r.error)throw r.error;rows.value=await Promise.all((r.data||[]).map(async m=>{const signed=await supabase!.storage.from('private-media').createSignedUrl(m.storage_path,300);if(signed.error)throw signed.error;return {...m,url:signed.data.signedUrl}}))}catch{error.value='附件暂时无法加载，请点击重试。'}finally{busy.value=false}}
function pick(e:Event){const selected=(e.target as HTMLInputElement).files?.[0];if(!selected)return;if(!['image/jpeg','image/png','image/webp'].includes(selected.type)||selected.size>4*1024*1024){error.value='请选择4MB以内的JPG、PNG或WebP图片';return}file.value=selected;error.value=''}
async function upload(){if(!file.value||!supabase||app.demo)return;busy.value=true;error.value='';try{const base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]!);reader.onerror=reject;reader.readAsDataURL(file.value!)});const r=await supabase.functions.invoke('link-media',{body:{link_id:props.linkId,mime:file.value.type,base64,attribution:attribution.value.trim(),is_ai_generated:ai.value}});if(r.error||r.data?.error)throw new Error('图片上传失败，请检查格式、数量及会话后重试');file.value=undefined;attribution.value='';await load();app.notify('图片已保存到私人附件，整理文章时确认许可后即可引用')}catch(e){error.value=app.errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="link-attachments"><div v-if="rows.length" class="article-gallery"><figure v-for="m in rows" :key="m.id"><img :src="m.url" :alt="m.attribution" loading="lazy" @error="error='图片链接过期或加载失败，请重试'"/><figcaption>{{m.attribution}}{{m.is_ai_generated?' · AI 示意图':''}} · 许可声明待确认</figcaption></figure></div><button class="source-link" @click="opened=!opened">{{opened?'收起上传':'添加有权使用的图片'}} · {{rows.length}} / 5</button><form v-if="opened" class="form-card" @submit.prevent="upload"><label>图片文件<input type="file" accept="image/jpeg,image/png,image/webp" @change="pick"/></label><label>作者、来源与使用许可<input v-model="attribution" maxlength="500" required placeholder="本人拍摄 / 作者 + CC许可 + 出处"/></label><label class="checkbox-label"><input v-model="ai" type="checkbox"/>AI生成示意图</label><button class="btn outline small" :disabled="busy||!file||!attribution.trim()||app.demo||rows.length>=5">保存私人图片</button><p class="form-hint">每条最多5张，每张4MB；不会自动复制原网站的未授权图片。</p></form><p v-if="error" class="form-error">{{error}} <button @click="load">重试</button></p></section></template>
